args.sparql:
SELECT DISTINCT ?person ?personLabel ?father ?fatherLabel ?paternalGrandmother ?paternalGrandmotherLabel WHERE {
  ?person rdfs:label ?personLabel .
  FILTER(
    CONTAINS(LCASE(STR(?personLabel)), "isabel") &&
    CONTAINS(LCASE(STR(?personLabel)), "beira")
  ) .
  {
    { ?person dbo:father ?father }
    UNION { ?person dbp:father ?father }
    UNION { ?person dbo:parent ?father }
    UNION { ?person dbp:parent ?father }
  }
  {
    { ?father dbo:mother ?paternalGrandmother }
    UNION { ?father dbp:mother ?paternalGrandmother }
    UNION { ?father dbo:parent ?paternalGrandmother }
    UNION { ?father dbp:parent ?paternalGrandmother }
  }
  OPTIONAL { ?father rdfs:label ?fatherLabel }
  OPTIONAL { ?paternalGrandmother rdfs:label ?paternalGrandmotherLabel }
} LIMIT 20

